import{_ as a}from"./_plugin-vue_export-helper-DlAUqK2U.js";import{M as r,bK as t,L as o}from"./index-DQ1L8GEQ.js";const i={},B={class:"chapter-content"};function e(d,E){return o(),r("div",B,[...E[0]||(E[0]=[t('<p class="article-lead">从白哈巴的木屋与喀纳斯的河湾，到赛里木湖的晚光、伊宁的街巷，再沿天山回程。这本路书陪四个人走完这段秋日旅途：出发前把准备做细，路上把目光留给风景。</p><div class="reading-guide"><p><strong>出发前</strong>读路线推导，核对订单与七项准备。</p><p><strong>每天前一晚</strong>打开次日章节，看时间轴与调整条件。</p><p><strong>旅途中</strong>需要吃住、拍摄或帮助时，直接查对应专题。</p></div><p><strong>10 月 9 日施工安排已核：</strong><a href="https://mp.weixin.qq.com/s?__biz=MzkyOTcyMTk4NA==&amp;mid=2247589180&amp;idx=1&amp;sn=13573abc92620933142b62fa753c5686&amp;chksm=c31cfc1e695cb9f4d6e4927bec2978d042354cd50d796560c942176561481e9fe0ef625dcaea&amp;scene=27" target="_blank" rel="noopener noreferrer">伊犁文旅转载景区公告</a>（公告落款 2026-08-22、转载 08-24）明确东沟全线 8 月 26 日起封闭，10 月 26 日仅为计划通车日期，游览按中沟进入，再从中沟原路返回。阿尤赛未被公告单独确认，不列入主行程；只有景区允许且能同路安全折返才另考虑，禁止进入东沟施工区。</p><p><strong>进镇先核施工导行：</strong><a href="https://www.xjgl.gov.cn/xjgl/c114161/202608/6d895a8ee07f4218a2d185898e548547.shtml" target="_blank" rel="noopener noreferrer">巩留县交通运输局公告</a>明确 X737 团结渠桥 9 月 1 日—11 月 30 日全封闭，主选按 S329 K8+200→X060→接回 X737 导行。现未核得该路口坐标与全线预计用时，旧直达值不能用于当前排程；11:30—12:00 到镇只是保守参考，遇延误缩短骑马或近处栈道，16:15 从喀峰返程的时间不后移。回新源走宝柯路、G578，不走 CZ18 白沟或牧道。</p><h2 id="单线定位">这趟旅程怎么走</h2><div class="callout is-note"><p>版本：<strong>v3.9 库尔德宁与独库北段</strong>｜D4 / D7 / D8 高德 MCP 复核：2026-09-30</p><p>奎屯站取还车的单一环线：乌鲁木齐站火车赴奎屯（D1 15:30 取车）→ 布尔津 → 白哈巴一晚 → D2 观鱼台、D3 三湾后提前返布尔津（备选 D3 同日游三湾与观鱼台、续住白哈巴） → 布尔津 → 克拉玛依 → 奎屯 → 赛里木湖 → 伊宁 → 库尔德宁 → 新源汉庭 → 唐布拉百里画廊 → 乔尔玛 → 独库北段 → 独山子 → 奎屯火车站服务点（D8 目标 17:00 抵达；封路改 G577 / G30）→ 火车回乌鲁木齐。现场按各日说明选择分支；想尝试可选体验，就用它替换原活动。</p></div><p><strong>人数：</strong>4 人（两间房）。</p><p><strong>车辆：</strong>理想 L8 2024 款 Pro（增程四驱、六座、魔毯空气悬架，95 号汽油），神州租车奎屯站取车，10.3 15:30 不变；10.10 改为 17:00—17:30 抵达奎屯火车站服务点（铁二路与团结南街交叉口西 200 米；POI B0MB9DU6A1，84.898292,44.405604），原合同 15:30 需改约，额外租车费待核。</p><p><strong>航班：</strong>HB862 10 月 2 日 18:45 起飞（14:30 深圳湾集合、15:00 过关打车、16:30 前到香港机场办值机与托运；到达时刻须核更新客票）；HX457 10 月 11 日 02:15 起飞，均按实际客票核对。</p><p><strong>火车：</strong>10-03 乌鲁木齐 12:30→奎屯 14:33（已定班次）；10-10 奎屯 18:06→乌鲁木齐 20:07（已定班次）。</p><p><strong>能源：</strong>加油为主、充电为机会项；油量低于 50% 开始规划油站，低于 30% 取消非必要停留。D6 晚间补油并准备 D7 08:00 实际发车。</p><p class="article-lead"><strong>全书只用北京时间。</strong>新疆地处中国西部，日照与常见用餐节奏相对偏晚；预约班车、酒店与摄影时，说清日期和北京时间。饭点可以按饥饿程度调整，列车、航班与已确认接驳按实际时刻执行。</p><h2 id="关键路线变化">关键路线变化</h2><ul><li><strong>D0：</strong>10 月 2 日 14:30 深圳湾口岸集合、15:00 起过关，四人四个 24 寸箱过关后在的士站找大尾箱，无合适车就即时叫一辆 PRIME／MPT，16:30 前到香港 T2 办值机与行李托运，完成手续后乘 APM 赴登机区，17:40 到登机口，HB862 18:45 起飞；10 月 3 日凌晨落地后不取车，打车约 19 km 入住维斯顿国际酒店（乌鲁木齐站北广场店，¥490 两间已订），尽快睡觉，D1 计划 11:00 起床、12:30 火车。</li><li><strong>D1：</strong>11:00 起床、12:30 火车；14:33 抵奎屯，站前简餐（或取车后大盘鸡）后 15:30 取车，预留 30 分钟验车，16:00 前后发车；双驾轮换并完整休息两次，预计 22:00—22:45 抵布尔津，五彩滩取消。</li><li><strong>D2：</strong>主选 08:00 起床，布尔津直达白哈巴预估 2.5—3 小时；12:00 入住，12:30 乘村内 2 号线到游客中心换乘去喀纳斯，下午观鱼台，末班返白哈巴。备选 10:00 起床、约 14:00 到村，下午游白哈巴。</li><li><strong>D3：</strong>主选 07:30 起床，08:00 新村停车场乘村内 2 路首班，08:30 白哈巴游客服务中心乘接驳车，10:00 前抵喀纳斯游客服务中心后换乘去神仙湾的区间车，再乘车到月亮湾、徒步到卧龙湾；目标 15:45 返白哈巴、最迟 16:30 前出发去布尔津，16:00 前返村且出发准备、路况均支持时可选铁贾公路，按预计到达时间避免夜路。备选同日游三湾与观鱼台，末班返白哈巴，晚上续住。</li><li><strong>D4：</strong>10:00 从布尔津鸿宇福瑞发车，经 G217、克拉玛依与 G3014 到奎屯，469.4 km / 5 h 27 min，不安排景点。</li><li><strong>D5：</strong>10:00 发车；G30 午餐与休息后约 15:45—16:05 到店。松树头是条件项，16:20 前准备就绪才出发、18:30 下撤；全天含约 58.6 km 湖区往返，20:04 日落、20:45 就近晚餐。</li><li><strong>D7：</strong>08:00 从伊宁亚朵实际驾车，09:30—09:50 完整休息；经交通局导行，11:30—12:00 参考到镇（施工可延后）。12:00—12:40 马家或特色老牌子拌面午餐，12:40—13:00 游客中心购票并核双向车流，13:00—13:50 经中沟、十里画廊到喀峰营地；13:50—16:10 齐梦德骑马上山、徒步下山。16:15 从喀峰营地开始返程，中沟原路返回，17:00—17:20 游客中心外休息，17:20 赴新源，19:00—19:30 到汉庭；19:45—20:45 就近晚餐并补油。</li><li><strong>D8：</strong>09:00 起床、09:40 从新源汉庭驾车；主选唐布拉 S316 / S315→乔尔玛→独库北段→独山子→奎屯火车站服务点，276.657 km / 5 h 08 min。那拉提线 314.139 km / 6 h 18 min 为受限备选：必要停车 75 min 后约 17:13 到点，仅当日全线纯驾驶明显缩短且交车与火车能够衔接才启用；共同北段封闭则走 G577 精伊公路转 G30，441.654 km / 5 h 37 min。目标 17:00 抵达，17:00—17:30 为到店窗口，交车另留 20—30 min；17:30 到店不保证赶上 18:06 火车。取消 90 min 收官饭，改打包或列车用餐；18:06—20:07 火车、20:30—23:30 桔子钟点房、23:30 赴机场不变。</li></ul><h2 id="数据真源约定">里程、订单与来源怎么查</h2><ul><li><strong>高德驾车基线：</strong><a href="#/chapter/01-%E7%A0%94%E7%A9%B6%E5%BA%95%E7%A8%BF" data-doc="01-研究底稿.md">01-研究底稿</a>；均为静态值，不含国庆车流、休息、检查与临时管制。</li><li><strong>住宿与订单：</strong>新源汉庭两间高级大床房 ¥294.22 已订，替代主线 10-09 住点。现行八晚 ¥5,877.92，含桔子钟点房 ¥198 为 ¥6,075.92；旧尼勒克订单退出主线，退改状态另核，不视为已取消。</li><li><strong>行前必查事项：</strong>G1—G7 见 <a href="#/chapter/03-%E5%85%A8%E4%B9%A6%E4%B8%80%E8%87%B4%E6%80%A7%E4%B8%8E%E6%94%BF%E7%AD%96%E6%97%B6%E6%95%88%E6%80%A7%E5%A4%8D%E6%A0%B8" data-doc="03-全书一致性与政策时效性复核.md">03-全书一致性</a>；奎屯站取还与两程火车票为 G1 核心，D2 核村内 2 号线、观鱼台与末班返村，D3 主选核 15:45 抵白哈巴的回程；备选同步核续住与 D4 09:00 白哈巴出发。</li><li><strong>证据与历史：</strong><a href="#/chapter/04-%E6%9D%A5%E6%BA%90%E4%B8%8E%E5%A4%8D%E6%A0%B8%E6%97%A5%E5%BF%97" data-doc="04-来源与复核日志.md">04-来源与复核日志</a>；旧路线订单仅可在历史/退改记录出现。</li></ul><p><strong>返程时间账：</strong>D8 09:40 发车，唐布拉主选必要停车 85 min（画廊 20、乔尔玛午餐 35、共同北段休息 20、补油 10），计入驾驶与必要停车后，预计抵达 16:12:33，至 17:00 留 47:27 道路缓冲。</p><p><strong>封路备选：</strong>G577 / G30 方案停车 80 min（首次休息 20、午餐 30、第二次休息 20、补油 10），计入必要停车后预计抵达 16:36:56，至 17:00 留 23:04 道路缓冲。</p><p><strong>那拉提条件备选：</strong>必要停车 75 min 后预计约 17:13 到达，距 17:30 仅约 17 min，交车与 18:06 火车衔接更紧；当前快照不作为正常可执行方案。只有当日全线纯驾驶明显缩短、全线开放，且休息、交车与火车衔接都已确认时，才可采用；若要 17:00 到点并留 30 min 道路缓冲，全线纯驾驶须≤5 h 35 min。</p><h2 id="卷册目录">从这里开始阅读</h2><div class="book-directory"><section class="book-directory__group"><h3 id="卷二日程">按天出发</h3><ul><li><a href="#/chapter/Day0-%E9%A6%99%E6%B8%AF-%E4%B9%8C%E9%B2%81%E6%9C%A8%E9%BD%90" data-doc="Day0-香港-乌鲁木齐.md">Day 0 · 香港 → 乌鲁木齐（凌晨落地）</a></li><li><a href="#/chapter/Day1-%E4%B9%8C%E9%B2%81%E6%9C%A8%E9%BD%90-%E5%B8%83%E5%B0%94%E6%B4%A5" data-doc="Day1-乌鲁木齐-布尔津.md">Day 1 · 乌鲁木齐 → 布尔津（长途转场）</a></li><li><a href="#/chapter/Day2-%E5%B8%83%E5%B0%94%E6%B4%A5-%E7%99%BD%E5%93%88%E5%B7%B4" data-doc="Day2-布尔津-白哈巴.md">Day 2 · 布尔津 → 白哈巴（进村日）</a></li><li><a href="#/chapter/Day3-%E7%99%BD%E5%93%88%E5%B7%B4-%E5%96%80%E7%BA%B3%E6%96%AF%E5%85%A8%E5%A4%A9" data-doc="Day3-白哈巴-喀纳斯全天.md">Day 3 · 白哈巴 → 条件喀纳斯 → 布尔津</a></li><li><a href="#/chapter/Day4-%E7%99%BD%E5%93%88%E5%B7%B4-%E5%85%8B%E6%8B%89%E7%8E%9B%E4%BE%9D-%E5%A5%8E%E5%B1%AF" data-doc="Day4-白哈巴-克拉玛依-奎屯.md">Day 4 · 布尔津 → 克拉玛依 → 奎屯</a></li><li><a href="#/chapter/Day5-%E5%A5%8E%E5%B1%AF-%E8%B5%9B%E9%87%8C%E6%9C%A8%E6%B9%96" data-doc="Day5-奎屯-赛里木湖.md">Day 5 · 奎屯 → 赛里木湖</a></li><li><a href="#/chapter/Day6-%E8%B5%9B%E9%87%8C%E6%9C%A8%E6%B9%96-%E4%BC%8A%E5%AE%81" data-doc="Day6-赛里木湖-伊宁.md">Day 6 · 赛里木湖环湖 → 伊宁</a></li><li><a href="#/chapter/Day7-%E4%BC%8A%E5%AE%81-%E9%82%A3%E6%8B%89%E6%8F%90-%E5%94%90%E5%B8%83%E6%8B%89-%E5%B0%BC%E5%8B%92%E5%85%8B" data-doc="Day7-伊宁-那拉提-唐布拉-尼勒克.md">Day 7 · 伊宁 → 库尔德宁骑马观景 → 新源</a></li><li><a href="#/chapter/Day8-%E5%B0%BC%E5%8B%92%E5%85%8B-%E4%B9%8C%E9%B2%81%E6%9C%A8%E9%BD%90" data-doc="Day8-尼勒克-乌鲁木齐.md">Day 8 · 新源 → 唐布拉 → 独库北段 → 奎屯还车 → 乌鲁木齐</a></li><li><a href="#/chapter/Day9-%E4%B9%8C%E9%B2%81%E6%9C%A8%E9%BD%90-%E9%A6%99%E6%B8%AF" data-doc="Day9-乌鲁木齐-香港.md">Day 9 · HX457 乌鲁木齐 → 香港 → 深圳</a></li></ul></section><section class="book-directory__group"><h3 id="卷三专题">随手查专题</h3><ul><li><a href="#/chapter/%E4%B8%93%E9%A2%98-%E6%99%AF%E5%8C%BA%E7%99%BE%E7%A7%91" data-doc="专题-景区百科.md">景区百科</a></li><li><a href="#/chapter/%E4%B8%93%E9%A2%98-%E7%90%86%E6%83%B3L8%E6%96%B0%E7%96%86%E8%87%AA%E9%A9%BE%E6%8C%87%E5%8D%97" data-doc="专题-理想L8新疆自驾指南.md">理想 L8 · 2024 款 Pro 新疆自驾指南</a></li><li><a href="#/chapter/%E4%B8%93%E9%A2%98-%E6%96%B0%E7%96%86%E6%91%84%E5%BD%B1%E5%9C%B0%E5%9B%BE" data-doc="专题-新疆摄影地图.md">新疆摄影地图</a></li><li><a href="#/chapter/%E4%B8%93%E9%A2%98-%E6%97%A0%E4%BA%BA%E6%9C%BA%E9%A3%9E%E8%A1%8C%E8%A7%84%E8%8C%83" data-doc="专题-无人机飞行规范.md">无人机飞行规范</a></li><li><a href="#/chapter/%E4%B8%93%E9%A2%98-%E9%85%92%E5%BA%97%E6%8C%87%E5%8D%97" data-doc="专题-酒店指南.md">酒店指南</a></li><li><a href="#/chapter/%E4%B8%93%E9%A2%98-%E7%BE%8E%E9%A3%9F%E6%8C%87%E5%8D%97" data-doc="专题-美食指南.md">美食指南</a></li><li><a href="#/chapter/%E4%B8%93%E9%A2%98-%E9%A2%84%E7%AE%97%E8%A7%84%E5%88%92" data-doc="专题-预算规划.md">预算规划</a></li><li><a href="#/chapter/%E4%B8%93%E9%A2%98-%E6%96%B0%E7%96%86%E6%97%85%E8%A1%8C%E5%BA%94%E6%80%A5%E5%AE%9D%E5%85%B8" data-doc="专题-新疆旅行应急宝典.md">新疆旅行应急宝典</a></li></ul></section><section class="book-directory__group"><h3 id="卷一总览">行前与来源</h3><ul><li><a href="#/chapter/01-%E7%A0%94%E7%A9%B6%E5%BA%95%E7%A8%BF" data-doc="01-研究底稿.md">研究底稿</a></li><li><a href="#/chapter/02-%E8%B7%AF%E7%BA%BF%E6%8E%A8%E5%AF%BC" data-doc="02-路线推导.md">路线推导：为什么是这一条单线</a></li><li><a href="#/chapter/03-%E5%85%A8%E4%B9%A6%E4%B8%80%E8%87%B4%E6%80%A7%E4%B8%8E%E6%94%BF%E7%AD%96%E6%97%B6%E6%95%88%E6%80%A7%E5%A4%8D%E6%A0%B8" data-doc="03-全书一致性与政策时效性复核.md">一致性与政策复核</a></li><li><a href="#/chapter/04-%E6%9D%A5%E6%BA%90%E4%B8%8E%E5%A4%8D%E6%A0%B8%E6%97%A5%E5%BF%97" data-doc="04-来源与复核日志.md">来源与复核日志</a></li></ul></section></div>',21)])])}const n=a(i,[["render",e]]);export{n as default};
